// 1. 短轮询：fetch + setInterval，注意带 since/lastId 做增量
function shortPolling() {
  let lastId = 0;
  setInterval(async () => {
    const resp = await fetch(`/api/messages?since=${lastId}`);
    const data = await resp.json();
    if (data.length > 0) lastId = data[data.length - 1].id;
  }, 3000);
}

// 2. 长轮询：while + AbortSignal.timeout，错误退避避免风暴
async function longPolling() {
  let lastId = 0;
  while (true) {
    try {
      const resp = await fetch(`/api/messages/subscribe?since=${lastId}`, {
        signal: AbortSignal.timeout(30000)
      });
      const data = await resp.json();
      if (data.length > 0) lastId = data[data.length - 1].id;
    } catch (e) {
      // 超时是正常路径，网络错则退避 1s 防止雪崩
      await new Promise(r => setTimeout(r, 1000));
    }
  }
}

// 3. SSE：EventSource 自动重连 + Last-Event-ID 续传
function sseDemo() {
  const es = new EventSource('/api/events');
  es.onmessage = e => render(JSON.parse(e.data));
  es.addEventListener('order-update', e => updateOrder(JSON.parse(e.data)));
  // 断网时浏览器自动带 Last-Event-ID 重连，服务端按该 ID 回放
}

// 4. WebSocket：必须业务层实现心跳 + 重连 + 消息补拉
function wsDemo() {
  let lastSeq = 0;
  let retries = 0; // 指数退避计数，必须初始化
  const connect = () => {
    const ws = new WebSocket(`wss://example.com/ws?since=${lastSeq}`);
    ws.onopen = () => {
      retries = 0; // 连上后重置退避
      // 应用层心跳 25s，小于 Nginx 默认 60s proxy_read_timeout，避免空闲断连
      ws.heartbeat = setInterval(() => ws.send('{"type":"ping"}'), 25000);
    };
    ws.onmessage = e => {
      const msg = JSON.parse(e.data);
      lastSeq = msg.seq;
      render(msg);
    };
    ws.onclose = ev => {
      clearInterval(ws.heartbeat);
      // 1000 正常关闭、1001 服务端 going away；1006 等异常断开才需重连，否则会风暴
      if (ev.code !== 1000 && ev.code !== 1001) setTimeout(connect, Math.min(30000, 1000 * 2 ** retries++));
    };
  };
  connect();
}

// 服务端 SSE 关键响应头（Express 示例）
app.get('/api/events', (req, res) => {
  res.setHeader('Content-Type', 'text/event-stream');
  res.setHeader('Cache-Control', 'no-cache');
  res.setHeader('Connection', 'keep-alive');
  res.setHeader('X-Accel-Buffering', 'no'); // 关键：关闭 Nginx 缓冲
  const hb = setInterval(() => res.write(':hb\n\n'), 25000);
  req.on('close', () => clearInterval(hb));
});
